/bin/bash -lc "nl -ba plugin/crew/tests/sabotage_autopilot.py | sed -n '150,350p'
tail -30 plugin/crew/tests/sabotage_autopilot.py
PYTHONDONTWRITEBYTECODE=1 python3 - <<'PY'
import sys
sys.path.insert(0,'plugin/crew/tests')
import sabotage_autopilot as s
from collections import Counter
print('all',len(s.AUTOPILOT_MUTATIONS),'deploy',len(s.DEPLOY_MUTATIONS))
for name,c in Counter(x[0] for x in s.AUTOPILOT_MUTATIONS).items():
 if c"'!=1: print('"'dup label',c,name)
for label,target,find,repl,test in s.AUTOPILOT_MUTATIONS:
 try: n=open(target,encoding='utf-8').read().count(find)
 except Exception as e: print('readfail',label,e); continue
 if n"'!=1: print('"'anchor',n,label,target)
PY"

